tool_outputs.stdout:
#!/usr/bin/env bash
set -u

if (( $# != 1 )); then
  echo "usage: order dependency-file" >&2
  exit 2
fi
input=$1
tmp=$(mktemp -d) || exit 2
trap 'rm -rf "$tmp"' EXIT

awk '
function trim(s) { sub(/^[ \t\r\n]+/, "", s); sub(/[ \t\r\n]+$/, "", s); return s }
{
  sub(/#.*/, "")
  if ($0 ~ /^[ \t]*$/) next
  colon = index($0, ":")
  if (!colon) next
  pkg = trim(substr($0, 1, colon - 1))
  rhs = trim(substr($0, colon + 1))
  if (pkg == "") next
  print pkg >> namesfile
  if (rhs != "") {
    n = split(rhs, deps, /[ \t\r\n]+/)
    for (i = 1; i <= n; i++) if (deps[i] != "") {
      print pkg "\t" deps[i] >> edgesfile
      print deps[i] >> namesfile
    }
  }
}
' namesfile="$tmp/names.raw" edgesfile="$tmp/edges" "$input"

LC_ALL=C sort -u "$tmp/names.raw" > "$tmp/names"
: > "$tmp/emitted"
while :; do
  awk -F '\t' '
    FILENAME == ARGV[1] { done[$0] = 1; next }
    FILENAME == ARGV[2] { names[++nn] = $0; next }
    FILENAME == ARGV[3] { if (!($2 in deps[$1])) deps[$1][$2] = 1; next }
    END {
      for (i = 1; i <= nn; i++) {
        p = names[i]; ready = !(p in done)
        if (ready) for (d in deps[p]) if (!(d in done)) { ready = 0; break }
        if (ready) print p
      }
    }
  ' "$tmp/emitted" "$tmp/names" "$tmp/edges" | LC_ALL=C sort > "$tmp/candidates"
  IFS= read -r next < "$tmp/candidates" || next=
  [[ -n $next ]] || break
  printf '%s\n' "$next"
  printf '%s\n' "$next" >> "$tmp/emitted"
done

awk '
  FILENAME == ARGV[1] { done[$0] = 1; next }
  { if (!($0 in done)) print }
' "$tmp/emitted" "$tmp/names" | LC_ALL=C sort > "$tmp/remaining"
if [[ -s $tmp/remaining ]]; then
  printf 'cycle: '
  paste -sd ' ' "$tmp/remaining" >&2
  exit 1
fi
exit 0
